class Solution:
    def pourWater(self, heights: List[int], volume: int, k: int) -> List[int]:
        n = len(heights)
        for _ in range(volume):
            best = k
            cur = heights[k]
            for i in range(k - 1, -1, -1):
                if heights[i] > cur:
                    break
                if heights[i] < cur:
                    cur = heights[i]
                    best = i
            if best != k:
                heights[best] += 1
                continue
            best = k
            cur = heights[k]
            for i in range(k + 1, n):
                if heights[i] > cur:
                    break
                if heights[i] < cur:
                    cur = heights[i]
                    best = i
            heights[best] += 1
        return heights

