class Solution {
public:
    vector<int> pourWater(vector<int>& heights, int volume, int k) {
        int n = heights.size();
        while (volume--) {
            int best = k, cur = heights[k];
            for (int i = k - 1; i >= 0; --i) {
                if (heights[i] > cur) break;
                if (heights[i] < cur) { cur = heights[i]; best = i; }
            }
            if (best != k) { heights[best]++; continue; }
            best = k; cur = heights[k];
            for (int i = k + 1; i < n; ++i) {
                if (heights[i] > cur) break;
                if (heights[i] < cur) { cur = heights[i]; best = i; }
            }
            heights[best]++;
        }
        return heights;
    }
};

