class Solution:
    def pourWater(self, heights: List[int], volume: int, k: int) -> List[int]:
        n = len(heights)

        def scan(step):
            best, cur = k, heights[k]
            i = k + step
            while 0 <= i < n and heights[i] <= heights[k]:
                if heights[i] < cur:
                    cur = heights[i]
                    best = i
                i += step
            return best

        for _ in range(volume):
            l = scan(-1)
            if heights[l] < heights[k]:
                heights[l] += 1
                continue
            r = scan(1)
            if heights[r] < heights[k]:
                heights[r] += 1
            else:
                heights[k] += 1
        return heights

