class Solution {
public:
    int scan(vector<int>& h, int k, int step) {
        int n = h.size(), best = k, cur = h[k];
        for (int i = k + step; i >= 0 && i < n && h[i] <= h[k]; i += step)
            if (h[i] < cur) { cur = h[i]; best = i; }
        return best;
    }
    vector<int> pourWater(vector<int>& heights, int volume, int k) {
        while (volume--) {
            int l = scan(heights, k, -1);
            if (heights[l] < heights[k]) { heights[l]++; continue; }
            int r = scan(heights, k, 1);
            if (heights[r] < heights[k]) heights[r]++;
            else heights[k]++;
        }
        return heights;
    }
};

